//! The wire contract of the tierstore trees interface: `proto/tierstore/trees/v1/trees.proto`,
//! package `tierstore.trees.v1`, service `TreesService` with `CreateTree`, `GetPlacement` and
//! `DeleteTree`.
//!
//! The messages are generated by `build.rs` and are in [`v1`]; the client stub
//! (`v1::trees_service_client`) comes with the `client` feature and the server trait and service
//! (`v1::trees_service_server`) with the `server` feature. The wire contract is only ever
//! extended (AGENTS.md B8): `tests/additive.rs` holds the released proto's descriptor as a golden
//! and fails on a removed, renumbered or retyped member.

/// The gRPC package of the contract; a later incompatible service is a `v2` package beside it.
pub const PACKAGE: &str = "tierstore.trees.v1";

/// The name of the service, as it is in the path of a call.
pub const SERVICE: &str = "TreesService";

/// The methods of the service, in the order of the proto.
pub const METHODS: [&str; 3] = ["CreateTree", "GetPlacement", "DeleteTree"];

/// The path of a call of `method` on the wire (`/tierstore.trees.v1.TreesService/CreateTree`),
/// which a signature of the call covers.
#[must_use]
pub fn path(method: &str) -> String {
    format!("/{PACKAGE}.{SERVICE}/{method}")
}

/// The generated messages and stubs.
#[expect(
    clippy::all,
    clippy::pedantic,
    clippy::nursery,
    missing_docs,
    reason = "generated by prost and tonic from trees.proto; its text is not ours to edit"
)]
pub mod v1 {
    include!(concat!(env!("OUT_DIR"), "/tierstore.trees.v1.rs"));
}
